-- Insert All 20 Verified Authentic Heritage Monuments
INSERT INTO slideshow_monuments (display_order, title, category, location, era, description, image_url, thumb_url, credit)
VALUES
(1, 'Virupaksha Temple & Sacred Landscape of Hampi', 'UNESCO World Heritage • Ancient Civilizations', 'Hampi, Bellary District, Karnataka', '7th–15th Century CE • Vijayanagara Empire', 'The sacred heart of the Vijayanagara Empire on the banks of Tungabhadra, where massive granite boulder landscapes embrace centuries-old Dravidian temple towers.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Complex_of_Virupaksha_Temple%2C_Hampi_%2804%29.jpg/1920px-Complex_of_Virupaksha_Temple%2C_Hampi_%2804%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Complex_of_Virupaksha_Temple%2C_Hampi_%2804%29.jpg/400px-Complex_of_Virupaksha_Temple%2C_Hampi_%2804%29.jpg', 'Wikimedia Commons / Dey.sandip'),
(2, 'Taj Mahal at Dawn Reflection', 'UNESCO World Heritage • Mughal Architecture', 'Agra, Uttar Pradesh', '1632–1653 CE • Mughal Imperial Epoch', 'An ivory-white marble mausoleum on the south bank of the Yamuna River, universally celebrated as the pinnacle of Indo-Islamic architectural symmetry.', 'https://images.unsplash.com/photo-1564507592333-c60657eea523?auto=format&fit=crop&w=2000&q=85', 'https://images.unsplash.com/photo-1564507592333-c60657eea523?auto=format&fit=crop&w=300&q=70', 'Jovyn Chamb / Unsplash'),
(3, 'Mysore Palace Golden Illumination', 'Royal Palaces & Citadels', 'Mysuru, Karnataka', '1897–1912 CE • Wadiyar Dynasty', 'The legendary Amba Vilas Palace bathed in ninety-seven thousand golden incandescent bulbs during festive dusk, showcasing magnificent Indo-Saracenic royal craftsmanship.', 'https://images.unsplash.com/photo-1590766940554-634a7ed41450?auto=format&fit=crop&w=2000&q=85', 'https://images.unsplash.com/photo-1590766940554-634a7ed41450?auto=format&fit=crop&w=300&q=70', 'Ashish Kumar / Unsplash'),
(4, 'Konark Sun Temple Celestial Chariot', 'UNESCO World Heritage • Kalinga Architecture', 'Konark, Puri District, Odisha', 'c. 1250 CE • Eastern Ganga Dynasty', 'Conceived as a colossal celestial chariot with 24 elaborately carved stone sundial wheels, pulled across the heavens by seven spirited stone horses.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Konarka_Temple.jpg/1920px-Konarka_Temple.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Konarka_Temple.jpg/400px-Konarka_Temple.jpg', 'Wikimedia Commons / G-u-t'),
(5, 'Ajanta Caves Buddhist Rock-Cut Monasteries', 'UNESCO World Heritage • Rock-Cut Sanctuaries', 'Aurangabad, Maharashtra', '2nd Century BCE – 480 CE • Satavahana & Vakataka', 'Horseshoe-shaped cliff sanctuaries harboring ancient Buddhist prayer halls, rock-cut stupas, and tempera murals chronicling the Jataka tales.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Ajanta_%2863%29.jpg/1920px-Ajanta_%2863%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Ajanta_%2863%29.jpg/400px-Ajanta_%2863%29.jpg', 'Wikimedia Commons / Vyacheslav Argenberg'),
(6, 'Kailasa Monolithic Rock Temple at Ellora', 'UNESCO World Heritage • Monolithic Engineering', 'Ellora Caves, Maharashtra', '8th Century CE • Rashtrakuta King Krishna I', 'The largest monolithic rock-cut monument on Earth, carved top-down out of a single vertical basalt cliff, removing over two hundred thousand tonnes of stone.', 'https://upload.wikimedia.org/wikipedia/en/f/fc/Kailash_temple_%28Ellora_cave_no_15%29_at_Verul.png', 'https://upload.wikimedia.org/wikipedia/en/thumb/f/fc/Kailash_temple_%28Ellora_cave_no_15%29_at_Verul.png/400px-Kailash_temple_%28Ellora_cave_no_15%29_at_Verul.png', 'Archaeological Survey of India / Verul'),
(7, 'Hampi Stone Chariot (Vittala Temple)', 'UNESCO World Heritage • Sacred Dravidian Architecture', 'Vittala Complex, Hampi, Karnataka', '16th Century CE • King Krishnadevaraya', 'An iconic granite shrine shaped as a procession chariot dedicated to Garuda, featuring intricately sculpted axles, wheels, and monolithic stone elephants.', 'https://upload.wikimedia.org/wikipedia/commons/b/bb/Stone_Chariot_at_Hampi%2C_Karnataka.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Stone_Chariot_at_Hampi%2C_Karnataka.jpg/400px-Stone_Chariot_at_Hampi%2C_Karnataka.jpg', 'Wikimedia Commons / Vinoth Chandar'),
(8, 'Kerala Backwaters & Wooden Kettuvallam', 'Ecological Heritage & Maritime Landscapes', 'Alappuzha, Kerala', 'Centuries-Old Indigenous Shipcraft Tradition', 'Tranquil emerald palm lagoons where ancestral wooden houseboats—assembled entirely of Anjili timber and coir knots without a single nail—glide through village waterways.', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=2000&q=85', 'https://images.unsplash.com/photo-1590050752117-238cb0fb12b1?auto=format&fit=crop&w=300&q=70', 'Sarath P / Unsplash'),
(9, 'Amber Fort Golden Sandstone Citadel', 'UNESCO World Heritage • Hill Forts of Rajasthan', 'Amer, Jaipur, Rajasthan', '1592 CE onwards • Raja Man Singh I', 'Imposing golden sandstone ramparts overlooking Maota Lake, preserving opulent courtyards, mirror-work Sheesh Mahal, and Rajput military architecture.', 'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=2000&q=85', 'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=300&q=70', 'Annie Spratt / Unsplash'),
(10, 'Varanasi Ghats & Sacred Riverfront', 'Living Sacred Rivers & Millennia-Old Traditions', 'Ahilya Ghat, Varanasi, Uttar Pradesh', 'Continuously Inhabited Since 1200 BCE', 'Ancient tiered riverfront steps along the sacred Ganges where morning rituals, wooden riverboats, and centuries-old sandstone temples reflect on the holy waters.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Ahilya_Ghat_by_the_Ganges%2C_Varanasi.jpg/1920px-Ahilya_Ghat_by_the_Ganges%2C_Varanasi.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Ahilya_Ghat_by_the_Ganges%2C_Varanasi.jpg/400px-Ahilya_Ghat_by_the_Ganges%2C_Varanasi.jpg', 'Wikimedia Commons / Gerd Eichmann'),
(11, 'Meenakshi Amman Temple & Polychrome Gopurams', 'Sacred Dravidian Architecture • Historic Temple Towns', 'Madurai, Tamil Nadu', '6th Century BCE Origins • 16th–17th Century Nayak Monumental Architecture', 'Fourteen monumental soaring gopuram gatehouses adorned with over thirty-three thousand vibrant, polychrome statues of deities, celestial musicians, and mythical beings.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/An_aerial_view_of_Madurai_city_from_atop_of_Meenakshi_Amman_temple.jpg/1920px-An_aerial_view_of_Madurai_city_from_atop_of_Meenakshi_Amman_temple.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/An_aerial_view_of_Madurai_city_from_atop_of_Meenakshi_Amman_temple.jpg/400px-An_aerial_view_of_Madurai_city_from_atop_of_Meenakshi_Amman_temple.jpg', 'Wikimedia Commons / Sankar 1995'),
(12, 'Bharatanatyam Sacred Classical Dance', 'Classical Performing Arts (Natya)', 'Tamil Nadu & Classical Indian Heritage', 'Codified in the Ancient Natya Shastra c. 200 BCE', 'The ancient art of storytelling through sculptured postures (karanas), codified hand mudras, expressive abhinaya, and resonant bronze bell anklets.', 'https://upload.wikimedia.org/wikipedia/commons/e/eb/Murugashankari_Leo.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Murugashankari_Leo.jpg/400px-Murugashankari_Leo.jpg', 'Wikimedia Commons / Leo Leo'),
(13, 'Yakshagana Mythological Folk Theatre', 'Living Intangible Cultural Traditions', 'Coastal Karnataka (Udupi & Uttara Kannada)', '16th Century Bhakti & Folk Epic Tradition', 'High-energy mythological folk-theatre distinguished by towering ornate headgear (pagade), facial makeup derived from natural mineral pigments, and roaring percussion.', 'https://upload.wikimedia.org/wikipedia/commons/e/e9/Yakshaganads.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Yakshaganads.jpg/400px-Yakshaganads.jpg', 'Wikimedia Commons / Dinesh Shenoy'),
(14, 'Kathakali Classical Dance-Drama of Kerala', 'UNESCO Intangible Heritage • Ritual Theatre', 'Kerala', '17th Century Kottarakkara Thampuran Tradition', 'An all-night Sanskrit-Malayalam dance drama where artists undergo hours of Chutti face sculpting to portray noble epic heroes with mesmerizing eye movements.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Kathakali_-Play_with_Kaurava.jpg/1920px-Kathakali_-Play_with_Kaurava.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Kathakali_-Play_with_Kaurava.jpg/400px-Kathakali_-Play_with_Kaurava.jpg', 'Wikimedia Commons / A.Davey'),
(15, 'Traditional Terracotta Diyas & Festive Rangoli', 'Sacred Festivals & Light Traditions', 'Pan-Indian Cultural Heritage', 'Ancient Vedic Observance', 'Hand-crafted clay diyas radiating warm illumination across vibrant rangoli patterns, celebrating the triumph of spiritual light over darkness.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/The_Rangoli_of_Lights.jpg/1920px-The_Rangoli_of_Lights.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/The_Rangoli_of_Lights.jpg/400px-The_Rangoli_of_Lights.jpg', 'Wikimedia Commons / Subhrajyoti07'),
(16, 'Channapatna Lacquerware & Wooden Handicrafts', 'GI-Protected Traditional Handicrafts', 'Channapatna, Ramanagara, Karnataka', '18th Century CE Royal Patronage • Tipu Sultan', 'World-renowned ivory-wood turned handicrafts polished with natural vegetable dyes and shellac, recognized with geographical indication (GI) status.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Wooden_toys.JPG/1920px-Wooden_toys.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Wooden_toys.JPG/400px-Wooden_toys.JPG', 'Wikimedia Commons / Hari Prasad Nadig'),
(17, 'Thrissur Pooram Grand Elephant Procession', 'Living Temple Pageantry & Agrarian Heritage', 'Vadakkunnathan Temple, Thrissur, Kerala', 'Established 1798 CE by Sakthan Thampuran', 'The Mother of all Poorams, featuring synchronized Panchavadyam drumming and the awe-inspiring Kudamattom exchange of brilliantly colored silk parasols.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Kudamatom_at_thrissur_pooram_2013_7618.JPG/1920px-Kudamatom_at_thrissur_pooram_2013_7618.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Kudamatom_at_thrissur_pooram_2013_7618.JPG/400px-Kudamatom_at_thrissur_pooram_2013_7618.JPG', 'Wikimedia Commons / Adarsh K'),
(18, 'Hoysaleswara Temple Sacred Stone Sculptures', 'UNESCO World Heritage • Sacred Hoysala Sculptures', 'Halebidu, Hassan District, Karnataka', '1121–1160 CE • Hoysala King Vishnuvardhana', 'Chloritic schist soapstone masterpieces with thousands of intricate relief sculptures depicting epic scenes, celestial dancers, and filigree jewelry carved in relief.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/Hoysaleshwara_temple_in_Monsoon.JPG/1920px-Hoysaleshwara_temple_in_Monsoon.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/Hoysaleshwara_temple_in_Monsoon.JPG/400px-Hoysaleshwara_temple_in_Monsoon.JPG', 'Wikimedia Commons / Dineshkannambadi'),
(19, 'Rani ki Vav Subterranean Stepwell Architecture', 'UNESCO World Heritage • Maru-Gurjara Architecture', 'Patan, Gujarat', '11th Century CE • Chaulukya Queen Udayamati', 'An inverted subterranean temple descending seven levels into the earth, lined with over five hundred major sculptures and intricate pillared pavilions.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Rani_ki_vav_02.jpg/1920px-Rani_ki_vav_02.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Rani_ki_vav_02.jpg/400px-Rani_ki_vav_02.jpg', 'Wikimedia Commons / Bernard Gagnon'),
(20, 'Lathmar Holi Celebration of Braj', 'Living Sacred Folk Festivals & Celebrations', 'Nandgaon & Barsana, Uttar Pradesh', 'Centuries-Old Cultural Heritage Tradition', 'An exhilarating cultural spectacle of unity and devotion where skies fill with organic vermilion and golden turmeric gulal clouds celebrating the eternal Radha-Krishna lore.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Lathmar_Holi_2022_in_Nandgaon%2C_Uttar_Pradesh_%28edited%29.jpg/1920px-Lathmar_Holi_2022_in_Nandgaon%2C_Uttar_Pradesh_%28edited%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Lathmar_Holi_2022_in_Nandgaon%2C_Uttar_Pradesh_%28edited%29.jpg/400px-Lathmar_Holi_2022_in_Nandgaon%2C_Uttar_Pradesh_%28edited%29.jpg', 'Wikimedia Commons / Subrata Roy')
